import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inp = scanner.nextLine();
        String segment = inp.substring(1, inp.length() - 1);
        int length_seg = segment.length();
        StringBuilder result_str = new StringBuilder();
        result_str.append(inp.charAt(0));
        int pos = 0;
        boolean found_at_char = false;
        while (pos < length_seg) {
            if (pos + 3 <= length_seg) {
                if (segment.substring(pos, pos + 3).equals("dot")) {
                    result_str.append(".");
                    pos += 3;
                    continue;
                }
            }
            if (pos + 2 <= length_seg && !found_at_char) {
                if (segment.substring(pos, pos + 2).equals("at")) {
                    result_str.append("@");
                    found_at_char = true;
                    pos += 2;
                    continue;
                }
            }
            result_str.append(segment.charAt(pos));
            pos += 1;
        }
        result_str.append(inp.charAt(inp.length() - 1));
        System.out.println(result_str.toString());
    }
}
